SELECT s.qmuser_user_id uid,s.session_id,s.aliyun_agent_id,s.trigger_source_type,s.title,s.dj_gmt_create,s.dj_last_active_time,EXISTS(SELECT 1 FROM ying99_qieman.qwen_a2a_session_map q WHERE q.session_id=s.session_id AND q.qmuser_user_id=s.qmuser_user_id AND q.is_deleted=0 AND q.created_at<'{{CUT}}') is_qwen,(SELECT COUNT(*) FROM ying99_xiaogu3_qa.agent_dj_messages m WHERE m.session_id=s.session_id AND m.is_deleted=0 AND m.role='USER' AND m.user_input IS NOT NULL AND TRIM(m.user_input)<>'' AND m.dj_gmt_create<'{{CUT}}') msgs FROM ying99_xiaogu3_qa.agent_dj_sessions s WHERE s.qmuser_user_id IN ({{IDS}}) AND s.is_deleted=0 AND s.dj_gmt_create<'{{CUT}}' ORDER BY uid,s.dj_gmt_create
